class BearerAuthMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next) -> Response:
        path = request.url.path
        if request.method == "OPTIONS" or any(path.startswith(p) for p in _AUTH_SKIP_PREFIXES):
            return await call_next(request)

        auth_header = request.headers.get("Authorization", "")
        if not auth_header.startswith("Bearer "):
            return JSONResponse(status_code=401, content={"detail": "Missing or malformed Authorization header"})
        token = auth_header[len("Bearer "):]
        if token != settings.api_dev_token:
            return JSONResponse(status_code=401, content={"detail": "Invalid bearer token"})
        return await call_next(request)

# backend/app/services/parser.py - 512-byte format detection
def detect_format(data: bytes) -> Literal["csv", "json", "xml"]:
    sample = data[:512].lstrip()
    if sample.startswith(b"<?xml") or sample.startswith(b"<"):
        return "xml"
    if sample and sample[0:1] in (b"[", b"{"):
        return "json"
    if sample:
        return "csv"
    raise ValueError("Could not detect format: file appears to be empty")

