def bulk_copy_insert(conn, rows: list[dict[str, Any]]) -> int:
    if not rows:
        return 0
    buf = io.StringIO()
    for row in rows:
        buf.write(_format_row(row) + "\n")
    buf.seek(0)
    with conn.cursor() as cur:
        cur.copy_expert(_COPY_SQL, buf)
    return len(rows)

