def _lookup_country(self, ip: str) -> Optional[str]:
    if self._city_db is None:
        return None
    try:
        rec = self._city_db.get(ip)
        if not rec: return None
        country = rec.get("country") or rec.get("registered_country")
        return country.get("iso_code") if country else None
