def _build_cospend_batch(rows: list[dict]) -> list[dict]:
    edges = []
    for r in rows:
        addrs = r["input_addresses"] or []
        if len(addrs) < 2:
            continue
        for a, b in itertools.combinations(addrs, 2):
            if a == b:
                continue
            addr1, addr2 = (a, b) if a < b else (b, a)
            edges.append({"addr1": addr1, "addr2": addr2})
    return edges

