# backend/scripts/detect_coinjoin.py - Epsilon-guarded window
def _max_equal_output_group(amounts: list[float], relative_tolerance: float) -> int:
    if not amounts:
        return 0
    sorted_amts = sorted(amounts)
    max_group = 1
    for i, base in enumerate(sorted_amts):
        if base <= 0: continue
        group = 1
        for j in range(i + 1, len(sorted_amts)):
            diff = (sorted_amts[j] - base) / max(sorted_amts[j], base)
            if diff <= relative_tolerance + 1e-9:
                group += 1
        if group > max_group:
            max_group = group
    return max_group

# Cumulative pass-through ratio calculation for peeling chains
def compute_pass_through_ratio(chain_hops: list[dict]) -> float:
    ratio = 1.0
    for hop in chain_hops:
        total_in = hop.get("total_in", 0.0)
        change_amt = hop.get("large_amt", 0.0)
        if total_in > 0:
            ratio *= (change_amt / total_in)
    return round(ratio, 4)

