# backend/app/ml/graph_transformer.py - Focal Loss implementation
class FocalLoss(nn.Module):
    def __init__(self, alpha: float = 6.20, gamma: float = 2.0):
        super().__init__()
        self.alpha = min(alpha, 20.0)
        self.gamma = gamma

    def forward(self, pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
        pred = pred.clamp(_EPS, 1.0 - _EPS)
        pt = torch.where(target == 1, pred, 1.0 - pred)
        at = torch.where(target == 1, self.alpha, 1.0)
        loss = -at * ((1.0 - pt) ** self.gamma) * torch.log(pt)
        return loss.mean()

