def compute_score(anomaly: float, risk: float, rules_count: int, is_mixing: bool) -> float:
    rule_bonus = min(rules_count, 5) / 5.0
    mixing_indicator = 1.0 if is_mixing else 0.0
    raw = 0.35 * anomaly + 0.45 * risk + 0.15 * rule_bonus + 0.05 * mixing_indicator
    return round(float(np.clip(raw, 0.0, 1.0)), 4)

