_store_lock = threading.RLock()

def upsert_batch(records: list[dict[str, Any]]) -> tuple[int, int]:
    upserted, skipped = 0, 0
    with _store_lock:
        for rec in records:
            addr = rec["address"]
            if addr not in _composite or rec.get("composite_score", 0) > _composite[addr].get("composite_score", 0):
                _composite[addr] = rec
                upserted += 1
            else:
                skipped += 1
    return upserted, skipped

